import{c as e,Q as n,j as a,m as t}from"./chunks/framework.DOi4mjdC.js";const i="/assets/%E9%9D%9E%E5%AF%B9%E9%BD%90%E6%90%AC%E5%85%A5-77.qevUouKL.png",l="/assets/%E9%9D%9E%E5%AF%B9%E9%BD%90%E6%90%AC%E5%87%BAureg%E4%B8%BA%E7%A9%BA.BexgOBBN.png",r="/assets/%E9%9D%9E%E5%AF%B9%E9%BD%90%E6%90%AC%E5%87%BAureg%E4%B8%8D%E4%B8%BA%E7%A9%BA.X7CuYFVc.png",p="/assets/msakReg%E8%BF%9E%E7%BB%AD%E9%9D%9E%E5%AF%B9%E9%BD%90%E6%90%AC%E5%87%BA.CZqvHQtE.png",g="/assets/%E9%9D%9E%E5%AF%B9%E9%BD%90%E6%90%AC%E5%85%A5%E6%90%AC%E5%87%BA%E7%A4%BA%E4%BE%8B.B2vK_1-f.png",m=JSON.parse('{"title":"连续非对齐场景优化","description":"","frontmatter":{},"headers":[{"level":1,"title":"连续非对齐场景优化","slug":"连续非对齐场景优化"},{"level":2,"title":"连续非对齐搬运优化建议","slug":"连续非对齐搬运优化建议"},{"level":2,"title":"连续非对齐搬运接口介绍","slug":"连续非对齐搬运接口介绍"},{"level":2,"title":"非对齐寄存器原理","slug":"非对齐寄存器原理"}],"relativePath":"guide/算子实践参考/SIMD算子性能优化/矢量计算/VF性能优化/连续非对齐场景优化.md","filePath":"guide/算子实践参考/SIMD算子性能优化/矢量计算/VF性能优化/连续非对齐场景优化.md"}'),o={name:"guide/算子实践参考/SIMD算子性能优化/矢量计算/VF性能优化/连续非对齐场景优化.md"};function d(u,s,c,_,A,B){return n(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="连续非对齐场景优化" tabindex="-1">连续非对齐场景优化 <a class="header-anchor" href="#连续非对齐场景优化" aria-label="Permalink to &quot;连续非对齐场景优化&quot;">​</a></h1><h2 id="连续非对齐搬运优化建议" tabindex="-1">连续非对齐搬运优化建议 <a class="header-anchor" href="#连续非对齐搬运优化建议" aria-label="Permalink to &quot;连续非对齐搬运优化建议&quot;">​</a></h2><ul><li>优先采用连续对齐搬运以避免额外开销，提升整体性能。</li><li>由于硬件支持限制，连续非对齐搬运时不建议使用AddrReg存储偏移量，推荐使用uint32_t类型存储偏移量，使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/%E8%BF%9E%E7%BB%AD%E9%9D%9E%E5%AF%B9%E9%BD%90%E6%90%AC%E5%85%A5.md" target="_blank" rel="noreferrer">post update</a>模式搬运，该场景下每次调用接口自动更新源操作数在UB上的地址。后续的优化建议均基于此场景展开。</li><li>连续非对齐搬入时，每次将UB数据搬运至RegTensor后，非对齐寄存器会缓存后续非对齐数据，下一次搬运时非对齐寄存器中的数据会写入RegTensor，因此连续非对齐搬入初始化仅需执行一次，应移至for循环外部。</li><li>连续非对齐搬出时，每次将RegTensor数据搬运至UB后，非对齐寄存器会缓存后续非对齐数据，下一次搬运时非对齐寄存器中缓存的数据将写入UB，因此连续非对齐搬出后处理只需执行一次，应移至for循环外部。</li></ul><p>【正例】</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 非对齐搬入初始化，使用uint32_t管理偏移量，移至for循环外部。</span></span>
<span class="line"><span>AscendC::Reg::LoadUnAlignPre(ureg0, srcAddr);</span></span>
<span class="line"><span>for (uint16_t i = 0; i &lt; repeatTimes; ++i) {</span></span>
<span class="line"><span>     AscendC::Reg::LoadUnAlign(srcReg, ureg0, srcAddr + i * postUpdateStride);</span></span>
<span class="line"><span>     AscendC::Reg::StoreUnAlign(dstAddr, srcReg, ureg1, postUpdateStride);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>// 非对齐搬出后处理，移至for循环外部。</span></span>
<span class="line"><span>AscendC::Reg::StoreUnAlignPost(dstAddr, ureg1, 0);</span></span></code></pre></div><p>【反例】</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>for (uint16_t i = 0; i &lt; repeatTimes; ++i) {</span></span>
<span class="line"><span>     AscendC::Reg::LoadUnAlignPre(ureg0, srcAddr + i * postUpdateStride);</span></span>
<span class="line"><span>     AscendC::Reg::LoadUnAlign(srcReg, ureg0, srcAddr + i * postUpdateStride);</span></span>
<span class="line"><span>     AscendC::Reg::StoreUnAlign(dstAddr, srcReg, ureg1, postUpdateStride);</span></span>
<span class="line"><span>     AscendC::Reg::StoreUnAlignPost(dstAddr, ureg1, 0);</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="连续非对齐搬运接口介绍" tabindex="-1">连续非对齐搬运接口介绍 <a class="header-anchor" href="#连续非对齐搬运接口介绍" aria-label="Permalink to &quot;连续非对齐搬运接口介绍&quot;">​</a></h2><p>为提升对不规则内存地址的处理能力，Reg矢量计算支持在数据搬运过程中对非32字节对齐的地址进行访问，适用于从UB向RegTensor非对齐搬运，或从RegTensor向UB非对齐搬运的场景。为降低非对齐访问带来的性能开销，RegBase引入非对齐寄存器缓存机制，该机制利用非对齐寄存器UnalignRegForLoad和UnalignRegForStore作为临时缓存区，用于暂存跨对齐边界的数据，从而实现高效的连续非对齐数据传输。</p><p>在读非对齐地址前，应该先通过LoadUnAlignPre进行初始化，然后再使用LoadUnAlign。在写非对齐地址时，先使用StoreUnAlign，再使用StoreUnAlignPost进行后处理。使用uint32_t管理偏移量的搬入搬出接口和maskReg搬出接口如下：</p><ul><li><p>连续非对齐搬入，使用uint32_t存储搬运量</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__simd_callee__ inline void LoadUnAlignPre(UnalignRegForLoad&amp; ureg, __ubuf__ T* srcAddr);</span></span>
<span class="line"><span>__simd_callee__ inline void LoadUnAlign(U&amp; dstReg, UnalignRegForLoad&amp; ureg, __ubuf__ T*&amp; srcAddr, uint32_t postUpdateStride);</span></span></code></pre></div></li><li><p>连续非对齐搬出，使用uint32_t存储偏移量</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__simd_callee__ inline void StoreUnAlign(__ubuf__ T*&amp; dstAddr, U&amp; srcReg, UnalignRegForStore&amp; ureg, uint32_t postUpdateStride);</span></span>
<span class="line"><span>__simd_callee__ inline void StoreUnAlignPost(__ubuf__ T*&amp; dstAddr, UnalignRegForStore&amp; ureg, int32_t postUpdateStride);</span></span></code></pre></div></li><li><p>连续非对齐搬出，将maskReg搬出至UB</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__simd_callee__ inline void StoreUnAlign(__ubuf__ T*&amp; dstAddr, MaskReg&amp; mask, UnalignRegForStore&amp; ureg);</span></span>
<span class="line"><span>__simd_callee__ inline void StoreUnAlignPost(__ubuf__ T*&amp; dstAddr, UnalignRegForStore&amp; ureg, int32_t postUpdateStride);</span></span></code></pre></div></li></ul><h2 id="非对齐寄存器原理" tabindex="-1">非对齐寄存器原理 <a class="header-anchor" href="#非对齐寄存器原理" aria-label="Permalink to &quot;非对齐寄存器原理&quot;">​</a></h2><p>本节主要介绍在非对齐搬运过程中，非对齐寄存器如何发挥其作用，并详细解释内部原理，帮助开发者理解为什么上文的性能优化建议能够带来性能收益。首先介绍连续非对齐数据搬入、连续非对齐数据搬出以及MaskReg连续非对齐数据搬出的实现原理，然后通过一个具体的搬入搬出例子将这些关键流程串接起来。</p><ul><li><p><strong>非对齐数据搬入</strong></p><p>如下图所示，从UB地址srcAddr ~ 304读取数据，并将其搬运至目标寄存器dstReg（256B）。处理流程如下：</p><ul><li><p>调用<strong>LoadUnAlignPre</strong>进行非对齐搬入初始化。非对齐寄存器ureg缓存UB地址32 ~ 64的有效数据，作为后续非对齐访问的前置数据缓存。</p></li><li><p>调用<strong>LoadUnAlign</strong>，硬件指令将UB地址64 ~ 320的数据搬入临时寄存器tmpReg，并将ureg中srcAddr ~ 64对应的数据与tmpReg中地址64 ~ 304对应的数据拼接在一起，将结果写入dstReg。本次搬运后，UB地址288 ~ 320的数据会被写入ureg。连续非对齐搬入时，由于LoadUnAlign会将后续未对齐的数据缓存至ureg，所以下一次搬入不需要再次调用LoadUnAlignPre，只需在第一次搬入前调用一次LoadUnAlignPre，从而实现非对齐搬入的性能优化。</p><p><strong>图 1</strong> 非对齐数据搬入</p><p><img src="`+i+'" alt=""></p></li></ul></li><li><p><strong>非对齐数据搬出</strong></p><p>将源寄存器srcReg中的非对齐数据写入UB地址dstAddr，根据ureg当前状态，分为两种场景：</p><p><strong>场景一：ureg为空</strong></p><ul><li>调用<strong>StoreUnAlign</strong>，此时ureg内无有效数据，表示连续非对齐搬出的起始状态，将srcReg中对应UB地址48 ~ 288的数据写入dstAddr，同步将srcReg中对应UB地址288 ~ 320的数据缓存至ureg。</li><li>调用<strong>StoreUnAlignPost</strong>进行非对齐搬出后处理。将ureg中缓存的UB地址288 ~ 320对应的有效数据写入UB。</li></ul><p><strong>图 2</strong> 非对齐数据搬出（ureg为空）</p><p><img src="'+l+'" alt=""></p><p><strong>场景二：ureg不为空</strong></p><ul><li>调用<strong>StoreUnAlign</strong>，此时ureg内有有效数据，系统将ureg中UB地址32 ~ dstAddr对应的数据与srcReg中UB地址dstAddr ~ 288对应的数据进行拼接，结果写入UB地址dstAddr。同步将srcReg中对应UB地址288 ~ 320的数据缓存至ureg。连续非对齐搬出时，由于当ureg不为空时，下一次StoreUnAlign会读本次StoreAUnlign缓存至ureg中数据，所以本次搬出不需调用StoreUnAlignPost，只需在搬出后调用一次StoreUnAlignPost，从而实现非对齐搬出的性能优化。</li><li>调用<strong>StoreUnAlignPost</strong>进行非对齐搬出后处理。将ureg中缓存的UB地址288 ~ 320对应的有效数据写入UB。</li></ul><p><strong>图 3</strong> 非对齐数据搬出（ureg不为空）</p><p><img src="'+r+'" alt=""></p></li><li><p><strong>MaskReg连续非对齐数据搬出</strong></p><p>将源寄存器MaskReg（32B）搬出至UB。</p><ul><li>UB地址上数据类型为b16时，硬件指令从每个2位数据中提取最低有效位（LSB），将MaskReg中32B数据打包成16B，写入UB。搬运完成后UB地址按16B偏移量更新。</li><li>UB地址上数据类型为b32时，硬件指令从每个4位数据中提取最低有效位（LSB），将MaskReg中32B数据打包成8B，写入UB。搬运完成后UB地址按8B偏移量更新。</li></ul><p>以UB地址上数据类型为b16为例，将两个MaskReg数据写入dstAddr ~ 72，按以下步骤进行非对齐搬出：</p><ul><li>将maskReg1压缩后的16B数据（UB地址dstAddr ~ 56）缓存至ureg。</li><li>将ureg中的数据与maskReg2压缩后的16B数据的部分数据（UB地址56 ~ 64）进行拼接，结果写入UB地址dstAddr ~ 64。</li><li>将maskReg2压缩后的16B数据的部分数据（UB地址64 ~ 72）缓存至ureg。</li><li>非对齐搬出后处理。将ureg中缓存的数据写入UB地址64 ~ 72。MaskReg连续非对齐搬出与RegTensor连续非对齐搬出类似，只需在搬出后调用一次StoreUnAlignPost，实现MaskReg连续非对齐搬出的性能优化。</li></ul><p><strong>图 4</strong> MaskReg连续非对齐数据搬出</p><p><img src="'+p+'" alt=""></p></li><li><p><strong>连续非对齐搬入搬出示例</strong></p><p>如下图，将UB地址48 ~ 560的uint32_t数据[1, 2, 3, ... , 128]搬入至dstReg，再搬回UB，需要两次搬入搬出操作，即for循环执行两次，初始化和后处理移至for循环外。</p><ol><li>非对齐搬入初始化：更新ureg1 = [1, 2, 3, 4]；</li><li>非对齐搬入：tmpReg =[5, 6, 7, ... , 68]，tmpReg部分数据和ureg1数据写入dstReg = [1, 2, 3, ... , 64]，更新ureg1 = [61, 62, 63, ... , 68];</li><li>非对齐搬出：dstReg部分数据[1, 2, 3, ... , 60]写入UB地址48 ~ 288，更新ureg2 = [61, 62, 63, 64]；</li><li>非对齐搬入：tmpReg = [69, 70, 71, ... ,128]，tmpReg数据和ureg1部分数据写入dstReg = [65, 66 67, ... , 128]；</li><li>非对齐搬出：ureg2数据[61, 62, 63, 64]和dstReg部分数据[65, 66, 67, ... ,124]写入UB地址288 ~ 544，更新ureg2 = [125, 126, 127, 128]；</li><li>非对齐搬出后处理：将ureg2中缓存的数据[125, 126, 127, 128]写入UB地址544 ~ 560。</li></ol><p><strong>图 5</strong> 连续非对齐搬入搬出</p><p><img src="'+g+'" alt=""></p></li></ul>',14)])])}const R=e(o,[["render",d]]);export{m as __pageData,R as default};
